import urllib.request
import urllib.error
import time

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url.rstrip('/')
        self.timeout = timeout

    def get(self, path):
        url = f"{self.base_url}{path}"
        for attempt in range(4):  # 0-3 attempts (4 total)
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                if e.code == 429:
                    if attempt < 3:
                        time.sleep(0.5 * (2 ** attempt))
                        continue
                    raise RateLimitError("Rate limit exceeded after 3 retries")
                elif 500 <= e.code < 600:
                    if attempt < 3:
                        time.sleep(1)
                        continue
                    raise ServerError(f"Server error {e.code} after 1 retry")
                else:  # 4xx (except 429)
                    raise ClientError(f"Client error {e.code}")
            except urllib.error.URLError:
                if attempt < 3:
                    time.sleep(1)
                    continue
                raise ConnectionError("Connection failed after 1 retry")

class RateLimitError(Exception):
    pass

class ServerError(Exception):
    pass

class ClientError(Exception):
    pass

class ConnectionError(Exception):
    pass
